head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[column > P > rowSpan]<br/>Studio 에서 GridView 의 Row 병합 시 사용되는 속성입니다.",
    "validation" : [
        "직접 수정 및 설정하는 것을 금합니다.",
        "Row 병합 시, 병합한 Row 의 수가 표시됩니다.",
        "Studio 의 '병합' 기능을 사용하면 자동 설정됩니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// target1 은 Studio 의 "병합" 기능으로 저장되는 형태(colSpan="" rowSpan="N")를 그대로 정적 선언한다.
//  - 직접 수정·설정 금지 속성이므로 con 옵션(임의 rowSpan 값 설정)과 재생성 버튼은 두지 않는다.
//  - Header / gBody 각 3 Line 구성 (한 레코드를 3 Line 으로 표시)
//    Line 1 : 상품코드(code, rowSpan=3) + 상품명(name) + 가격(price)
//    Line 2 : (code 점유) + 분류(category, rowSpan=2) + 재고(stock)
//    Line 3 : (code, category 점유) + 비고(memo)



// validation 2 판정 출력 : 0번째 Row 에서 rowSpan 이 저장된 Column 셀의 rowspan 과 실제로 걸쳐 표시되는 Line 범위
scwin.btn_checkRowSpan_onclick = function () {
    let trList = scwin.getRecordLines(0);
    let arrCol = [ { id : "code", label : "상품코드" }, { id : "category", label : "분류" } ];
    for (let i = 0; i < arrCol.length; i++) {
        let td = scwin.getBodyCell(trList, arrCol[i].id);
        if (!td) {
            wf_body_bottom.getObj("scwin").setReturnValue(arrCol[i].label + "(" + arrCol[i].id + ") : 셀 없음");
            continue;
        }
        let rect = td.getBoundingClientRect();
        let arrLine = [];
        for (let j = 0; j < trList.length; j++) {
            let trRect = trList[j].getBoundingClientRect();
            // 셀 영역이 Line(tr) 의 세로 중앙을 포함하면 해당 Line 에 걸쳐 표시된 것으로 판정
            let mid = trRect.top + trRect.height / 2;
            if (rect.top <= mid && mid <= rect.bottom) {
                arrLine.push(j + 1);
            }
        }
        let strLine = (arrLine.length > 0) ? "Line " + arrLine.join(", ") + " 에 걸쳐 표시 (" + arrLine.length + "개 Row)" : "걸친 Line 없음";
        wf_body_bottom.getObj("scwin").setReturnValue(arrCol[i].label + "(" + arrCol[i].id + ") '" + td.textContent + "' : rowspan " + (td.getAttribute("rowspan") || "없음") + " -> " + strLine);
    }
}



// rowIndex 번째 레코드를 구성하는 Body Line(tr) 목록
scwin.getRecordLines = function (rowIndex) {
    let lineCnt = 3;
    let tbody = document.querySelector("#" + target1.id + "_body_tbody");
    let trList = tbody ? Array.prototype.filter.call(tbody.children, function (tr) { return tr.tagName === "TR" && tr.style.display !== "none" && tr.querySelector("td"); }) : [];
    return trList.slice(rowIndex * lineCnt, rowIndex * lineCnt + lineCnt);
}



// Line 목록에서 지정 Column 의 셀(td) 탐색 (data-col_id 기준)
scwin.getBodyCell = function (trList, colId) {
    for (let i = 0; i < trList.length; i++) {
        let td = trList[i].querySelector("td[data-col_id='" + colId + "']");
        if (td) {
            return td;
        }
    }
    return null;
}
